    printf(COMP_R_NATIVE_LOG_PREFIX " start candidate=%s schema=v1 geometry=24x24 black_pixels=448 nodes=A0..A8..A0 path=A0..A8..A0 step_px=12 travel_px=96 apex_px=48 framebuffer=200x200 diff=exact_previous_current_union corridor=3-19,64-135 corridor_bytes=1224 full_current_rewrite=1 control=0xCF baseline_control=0xFF movement_reset=0 activation=1 busy_limit_ms=600 transaction_limit_ms=460 cadence_limit_ms=480 cadence_target_ms=450 ring=65536 production_enabled=0\r\n", R10_NATIVE_TWO_PASS_CANDIDATE);
