    printf("[epaper] %s armed telemetry_storage=host_ring_65536 popup_commands=0 production_enabled=0\r\n", R10_NATIVE_TWO_PASS_CANDIDATE);
    printf("[epaper] %s start candidate=%s schema=%s geometry=%s black_pixels=%u y=80 x_start=32 x_end=64 step_px=2 travel_px=32 path=ping_pong framebuffer=200x200 diff=exact_previous_current_union stage_command=0x24 source_reset_border=baseline_only movement_reset=0 control=0xCF refresh=0x20 busy_limit_ms=600 transaction_limit_ms=455 cadence_target_ms=490 cadence_improvement_target_ms=470 otp_mode2=1 motion_0x26_writes=0 controls_32=0 controls_37=0 custom_lut=0 full_frame_writes=0 third_activation=0 retries=0 maintenance_refreshes=0 production_enabled=0\r\n", R10_NATIVE_TWO_PASS_CANDIDATE, R10_NATIVE_TWO_PASS_CANDIDATE, R10_NATIVE_TWO_PASS_SCHEMA, COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_SIZE == 24u ? "24x24" : "12x12", (unsigned)COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_BLACK_PIXELS);
#elif COMPANION_EPAPER_SSD1681_R10_NATIVE_GUARDED_CORRIDOR_NO_RESET_CADENCE_DIAGNOSTIC
    printf("[epaper] %s start candidate=%s schema=%s geometry=%s black_pixels=%u y=80 x_start=32 x_end=64 step_px=2 travel_px=32 path=ping_pong framebuffer=200x200 diff=exact_previous_current_union stage_command=0x24 source_reset_border=baseline_only movement_reset=0 control=0xFF refresh=0x20 busy_limit_ms=600 transaction_limit_ms=455 cadence_target_ms=490 otp_mode2=1 motion_0x26_writes=0 controls_32=0 controls_37=0 custom_lut=0 full_frame_writes=0 third_activation=0 retries=0 maintenance_refreshes=0 production_enabled=0\r\n", R10_NATIVE_TWO_PASS_CANDIDATE, R10_NATIVE_TWO_PASS_CANDIDATE, R10_NATIVE_TWO_PASS_SCHEMA, COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_SIZE == 24u ? "24x24" : "12x12", (unsigned)COMP_R10_NATIVE_TWO_PASS_FINE_STRIDE_BLACK_PIXELS);
