    printf(COMP_R_NATIVE_LOG_PREFIX " baseline frame=0 window=0-24,0-199 bytes=5000 resets=1 ready_checks=1 command=0x24 control=0xFF refresh=0x20 activations=1 t=%lu b=%lu\r\n", (unsigned long)baseline_transaction_elapsed_ms, (unsigned long)baseline_busy);
