    printf(COMP_R_NATIVE_LOG_PREFIX " baseline candidate=%s x=32 activations=1 source_activation=1 source_resets=1 ready_checks=1 source_ff=1 source_cf=0 movement_source_resets=0 movement_source_ff=0 movement_source_cf=1 forbidden=0 landing=1 reset_elapsed_ms=%lu transaction_elapsed_ms=%lu busy_elapsed_ms=%lu\r\n", R10_NATIVE_TWO_PASS_CANDIDATE, (unsigned long)baseline_reset_elapsed_ms, (unsigned long)baseline_transaction_elapsed_ms, (unsigned long)baseline_busy);
